import { describe, expect, it } from "vitest";
import { canonicalQuery, trailKey } from "./search-normalize.js";

describe("canonicalQuery", () => {
  it("collapses case, whitespace, punctuation, order, and duplicates", () => {
    expect(canonicalQuery("Cold Start  Lambda")).toBe(
      canonicalQuery("lambda cold start"),
    );
    expect(canonicalQuery("AWS, Lambda! Lambda")).toBe("aws lambda");
  });

  it("keeps year tokens because recency changes cache intent", () => {
    expect(canonicalQuery("lambda pricing 2025")).not.toBe(
      canonicalQuery("lambda pricing"),
    );
  });
});

describe("trailKey", () => {
  it("collapses bare-year variants so the advisory list catches them", () => {
    expect(trailKey("cloudflare cpu limit free paid plan")).toBe(
      trailKey("cloudflare cpu limit free paid plan 2024 2025"),
    );
  });

  it("falls back to the raw query when only years are present", () => {
    expect(trailKey("2024 2025")).toBe("2024 2025");
  });
});

import type {
  LanguageModelV3,
  LanguageModelV3GenerateResult,
  LanguageModelV3StreamPart,
} from "@ai-sdk/provider";
import { generateText, simulateReadableStream, streamText } from "ai";
import { MockLanguageModelV3 } from "ai/test";
import { describe, expect, it } from "vitest";
import { createConcurrencyGate, sleep } from "./async.js";
import { createBudgetMeter } from "./budget.js";
import { AtlasError } from "./errors.js";
import {
  createModelCallCache,
  createRunUsage,
  engineModel,
  normalizeForCacheKey,
  type ResolvedModel,
  totalFreshTokens,
} from "./model.js";
import {
  JournalWriter,
  loadReplayCache,
  memoryStore,
} from "./providers/store.js";

const RESULT: LanguageModelV3GenerateResult = {
  content: [{ type: "text", text: "hello" }],
  finishReason: { unified: "stop", raw: undefined },
  usage: {
    inputTokens: {
      total: 1_000_000,
      noCache: 1_000_000,
      cacheRead: 0,
      cacheWrite: 0,
    },
    outputTokens: { total: 0, text: 0, reasoning: 0 },
  },
  warnings: [],
};

function mock(provider = "mock-provider", modelId = "claude-sonnet-4-6") {
  return new MockLanguageModelV3({
    provider,
    modelId,
    doGenerate: RESULT,
  });
}

describe("engineModel", () => {
  it("charges usage cost against the grant", async () => {
    const meter = createBudgetMeter(10);
    const inner = mock();
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "lead",
      grant: meter,
      pricing: { "claude-sonnet-4-6": { inputPerMTok: 3, outputPerMTok: 15 } },
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
    });
    const result = await generateText({
      model: model as LanguageModelV3,
      prompt: "hi",
    });
    expect(result.text).toBe("hello");
    expect(meter.totalSpentUSD()).toBeCloseTo(3);
  });

  it("reserves estimated cost while a call is in flight", async () => {
    const meter = createBudgetMeter(10);
    let releaseCall!: () => void;
    const inFlight = new Promise<void>((resolve) => {
      releaseCall = resolve;
    });
    const inner = new MockLanguageModelV3({
      provider: "mock-provider",
      modelId: "claude-sonnet-4-6",
      doGenerate: async () => {
        await inFlight;
        return RESULT;
      },
    });
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "lead",
      grant: meter,
      pricing: { "claude-sonnet-4-6": { inputPerMTok: 3, outputPerMTok: 15 } },
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
    });
    const pending = generateText({
      model: model as LanguageModelV3,
      prompt: "hi",
    });
    await new Promise((resolve) => setTimeout(resolve, 10));
    expect(meter.remainingUSD()).toBeLessThan(10);
    expect(meter.totalSpentUSD()).toBe(0);
    releaseCall();
    await pending;
    expect(meter.remainingUSD()).toBeCloseTo(7);
    expect(meter.totalSpentUSD()).toBeCloseTo(3);
  });

  it("hard-stops a model call once the run budget is exhausted", async () => {
    const inner = mock();
    let exhausted = false;
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "write",
      grant: createBudgetMeter(10),
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      budgetExhausted: () => exhausted,
    });
    await generateText({ model: model as LanguageModelV3, prompt: "first" });
    expect(inner.doGenerateCalls).toHaveLength(1);
    exhausted = true;
    await expect(
      generateText({ model: model as LanguageModelV3, prompt: "second" }),
    ).rejects.toThrow(AtlasError);
    expect(inner.doGenerateCalls).toHaveLength(1);
  });

  it("serves an identical call from the run cache without re-invoking or recharging", async () => {
    const meter = createBudgetMeter(10);
    const inner = mock();
    let cacheHits = 0;
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "write",
      grant: meter,
      pricing: { "claude-sonnet-4-6": { inputPerMTok: 3, outputPerMTok: 15 } },
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      modelCache: createModelCallCache(),
      onCacheHit: () => {
        cacheHits++;
      },
    });
    const first = await generateText({
      model: model as LanguageModelV3,
      prompt: "same",
    });
    const second = await generateText({
      model: model as LanguageModelV3,
      prompt: "same",
    });
    expect(first.text).toBe("hello");
    expect(second.text).toBe("hello");
    expect(inner.doGenerateCalls).toHaveLength(1);
    expect(meter.totalSpentUSD()).toBeCloseTo(3);
    expect(cacheHits).toBe(1);
  });

  it("issues a fresh call when the prompt differs", async () => {
    const inner = mock();
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "write",
      grant: createBudgetMeter(10),
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      modelCache: createModelCallCache(),
    });
    await generateText({ model: model as LanguageModelV3, prompt: "alpha" });
    await generateText({ model: model as LanguageModelV3, prompt: "beta" });
    expect(inner.doGenerateCalls).toHaveLength(2);
  });

  it("tracks usage per role", async () => {
    const usage = createRunUsage();
    const meter = createBudgetMeter(10);
    const model = engineModel(mock() as unknown as ResolvedModel, {
      role: "write",
      grant: meter,
      pricing: {},
      gate: createConcurrencyGate(2),
      usage,
    });
    await generateText({ model: model as LanguageModelV3, prompt: "hi" });
    expect(usage.byRole.get("write")?.input).toBe(1_000_000);
  });

  it("journals calls and replays them without re-invoking the model", async () => {
    const store = memoryStore();
    const journal = new JournalWriter(store, "run_1");
    const meter = createBudgetMeter(10);
    const first = mock();
    const firstModel = engineModel(first as unknown as ResolvedModel, {
      role: "lead",
      grant: meter,
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      journal,
    });
    const liveResult = await generateText({
      model: firstModel as LanguageModelV3,
      prompt: "same question",
    });
    await journal.flush();
    expect(first.doGenerateCalls).toHaveLength(1);

    const replay = await loadReplayCache(store, "run_1");
    const meter2 = createBudgetMeter(10);
    const second = mock();
    const usage2 = createRunUsage();
    const secondModel = engineModel(second as unknown as ResolvedModel, {
      role: "lead",
      grant: meter2,
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: usage2,
      replay,
    });
    const replayed = await generateText({
      model: secondModel as LanguageModelV3,
      prompt: "same question",
    });
    expect(second.doGenerateCalls).toHaveLength(0);
    expect(replayed.text).toBe(liveResult.text);
    expect(meter2.totalSpentUSD()).toBe(meter.totalSpentUSD());
    expect(usage2.replayedUSD).toBe(meter2.totalSpentUSD());
  });

  it("replays a call when only the volatile budget readout changed", async () => {
    const store = memoryStore();
    const journal = new JournalWriter(store, "run_budget");
    const first = mock();
    const firstModel = engineModel(first as unknown as ResolvedModel, {
      role: "lead",
      grant: createBudgetMeter(10),
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      journal,
    });
    await generateText({
      model: firstModel as LanguageModelV3,
      prompt: "find X\n\n[budget: ≈$9.80 of $10.00 remaining]",
    });
    await journal.flush();
    expect(first.doGenerateCalls).toHaveLength(1);

    const replay = await loadReplayCache(store, "run_budget");
    const second = mock();
    const secondModel = engineModel(second as unknown as ResolvedModel, {
      role: "lead",
      grant: createBudgetMeter(10),
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      replay,
    });
    const replayed = await generateText({
      model: secondModel as LanguageModelV3,
      // Same logical step on resume, but the live budget figure differs.
      prompt: "find X\n\n[budget: ≈$2.13 of $10.00 remaining]",
    });
    expect(second.doGenerateCalls).toHaveLength(0);
    expect(replayed.text).toBe("hello");
  });

  it("does not replay across a real content change with the same shape", async () => {
    const store = memoryStore();
    const journal = new JournalWriter(store, "run_price");
    const first = mock();
    const firstModel = engineModel(first as unknown as ResolvedModel, {
      role: "lead",
      grant: createBudgetMeter(10),
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      journal,
    });
    await generateText({
      model: firstModel as LanguageModelV3,
      prompt: "the listed price was $5.00",
    });
    await journal.flush();

    const replay = await loadReplayCache(store, "run_price");
    const second = mock();
    const secondModel = engineModel(second as unknown as ResolvedModel, {
      role: "lead",
      grant: createBudgetMeter(10),
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      replay,
    });
    await generateText({
      model: secondModel as LanguageModelV3,
      // Exact "$" figures are not normalized: this is a different prompt.
      prompt: "the listed price was $7.00",
    });
    expect(second.doGenerateCalls).toHaveLength(1);
  });

  it("injects an anthropic cache breakpoint on the last message", async () => {
    const inner = mock("anthropic.messages", "claude-sonnet-4-6");
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "lead",
      grant: createBudgetMeter(10),
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
    });
    await generateText({ model: model as LanguageModelV3, prompt: "hi" });
    const params = inner.doGenerateCalls[0];
    const last = params.prompt[params.prompt.length - 1];
    expect(last.providerOptions?.anthropic?.cacheControl).toEqual({
      type: "ephemeral",
    });
  });

  it("leaves non-anthropic prompts untouched", async () => {
    const inner = mock("openai.responses", "gpt-5.5");
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "lead",
      grant: createBudgetMeter(10),
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
    });
    await generateText({ model: model as LanguageModelV3, prompt: "hi" });
    const params = inner.doGenerateCalls[0];
    const last = params.prompt[params.prompt.length - 1];
    expect(last.providerOptions?.anthropic).toBeUndefined();
  });

  it("retries a retryable failure and reports it via onRateLimit", async () => {
    let calls = 0;
    const inner = new MockLanguageModelV3({
      provider: "mock-provider",
      modelId: "claude-sonnet-4-6",
      doGenerate: async () => {
        calls++;
        if (calls === 1) {
          throw Object.assign(
            new Error(
              "Number of concurrent connections has exceeded your rate limit",
            ),
            { statusCode: 429, isRetryable: true },
          );
        }
        return RESULT;
      },
    });
    const notices: number[] = [];
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "lead",
      grant: createBudgetMeter(10),
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      onRateLimit: (notice) => notices.push(notice.attempt),
    });
    const result = await generateText({
      model: model as LanguageModelV3,
      prompt: "hi",
      maxRetries: 0,
    });
    expect(result.text).toBe("hello");
    expect(calls).toBe(2);
    expect(notices).toEqual([1]);
  });

  it("does not retry a non-retryable failure", async () => {
    let calls = 0;
    const inner = new MockLanguageModelV3({
      provider: "mock-provider",
      modelId: "claude-sonnet-4-6",
      doGenerate: async () => {
        calls++;
        throw Object.assign(new Error("invalid request"), {
          statusCode: 400,
          isRetryable: false,
        });
      },
    });
    const notices: number[] = [];
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "lead",
      grant: createBudgetMeter(10),
      pricing: {},
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      onRateLimit: (notice) => notices.push(notice.attempt),
    });
    await expect(
      generateText({
        model: model as LanguageModelV3,
        prompt: "hi",
        maxRetries: 0,
      }),
    ).rejects.toThrow(/invalid request/);
    expect(calls).toBe(1);
    expect(notices).toEqual([]);
  });

  it("holds the gate slot across a rate-limit backoff", async () => {
    const gate = createConcurrencyGate(1);
    const order: string[] = [];
    let slowCalls = 0;
    const slow = new MockLanguageModelV3({
      provider: "mock-provider",
      modelId: "claude-sonnet-4-6",
      doGenerate: async () => {
        slowCalls++;
        if (slowCalls === 1) {
          throw Object.assign(
            new Error(
              "Number of concurrent connections has exceeded your rate limit",
            ),
            { statusCode: 429, isRetryable: true },
          );
        }
        order.push("slow");
        return RESULT;
      },
    });
    const fast = new MockLanguageModelV3({
      provider: "mock-provider",
      modelId: "claude-sonnet-4-6",
      doGenerate: async () => {
        order.push("fast");
        return RESULT;
      },
    });
    const base = {
      role: "lead" as const,
      pricing: {},
      gate,
      usage: createRunUsage(),
    };
    const slowModel = engineModel(slow as unknown as ResolvedModel, {
      ...base,
      grant: createBudgetMeter(10),
    });
    const fastModel = engineModel(fast as unknown as ResolvedModel, {
      ...base,
      grant: createBudgetMeter(10),
    });
    const slowP = generateText({
      model: slowModel as LanguageModelV3,
      prompt: "slow",
      maxRetries: 0,
    });
    await sleep(50);
    const fastP = generateText({
      model: fastModel as LanguageModelV3,
      prompt: "fast",
      maxRetries: 0,
    });
    await Promise.all([slowP, fastP]);
    expect(order).toEqual(["slow", "fast"]);
    expect(slowCalls).toBe(2);
  });

  it("frees the gate slot during a non-rate-limit backoff", async () => {
    const gate = createConcurrencyGate(1);
    const order: string[] = [];
    let slowCalls = 0;
    const slow = new MockLanguageModelV3({
      provider: "mock-provider",
      modelId: "claude-sonnet-4-6",
      doGenerate: async () => {
        slowCalls++;
        if (slowCalls === 1) {
          throw Object.assign(new Error("service unavailable"), {
            statusCode: 503,
            isRetryable: true,
          });
        }
        order.push("slow");
        return RESULT;
      },
    });
    const fast = new MockLanguageModelV3({
      provider: "mock-provider",
      modelId: "claude-sonnet-4-6",
      doGenerate: async () => {
        order.push("fast");
        return RESULT;
      },
    });
    const base = {
      role: "lead" as const,
      pricing: {},
      gate,
      usage: createRunUsage(),
    };
    const slowModel = engineModel(slow as unknown as ResolvedModel, {
      ...base,
      grant: createBudgetMeter(10),
    });
    const fastModel = engineModel(fast as unknown as ResolvedModel, {
      ...base,
      grant: createBudgetMeter(10),
    });
    const slowP = generateText({
      model: slowModel as LanguageModelV3,
      prompt: "slow",
      maxRetries: 0,
    });
    await sleep(50);
    const fastP = generateText({
      model: fastModel as LanguageModelV3,
      prompt: "fast",
      maxRetries: 0,
    });
    await Promise.all([slowP, fastP]);
    expect(order).toEqual(["fast", "slow"]);
    expect(slowCalls).toBe(2);
  });
});

describe("engineModel streaming", () => {
  const PRICING = {
    "claude-sonnet-4-6": { inputPerMTok: 3, outputPerMTok: 15 },
  };

  function streamingMock(): MockLanguageModelV3 {
    return new MockLanguageModelV3({
      provider: "mock-provider",
      modelId: "claude-sonnet-4-6",
      doStream: async () => ({
        stream: simulateReadableStream<LanguageModelV3StreamPart>({
          chunks: [
            { type: "stream-start", warnings: [] },
            { type: "text-start", id: "t1" },
            { type: "text-delta", id: "t1", delta: "hello " },
            { type: "text-delta", id: "t1", delta: "world" },
            { type: "text-end", id: "t1" },
            {
              type: "finish",
              finishReason: { unified: "stop", raw: undefined },
              usage: RESULT.usage,
            },
          ],
        }),
      }),
    });
  }

  it("meters and journals a streamed call", async () => {
    const store = memoryStore();
    const journal = new JournalWriter(store, "run_stream");
    const meter = createBudgetMeter(10);
    const inner = streamingMock();
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "write",
      grant: meter,
      pricing: PRICING,
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
      journal,
    });
    const result = streamText({
      model: model as LanguageModelV3,
      prompt: "hi",
    });
    let text = "";
    for await (const delta of result.textStream) text += delta;
    expect(text).toBe("hello world");
    expect(meter.totalSpentUSD()).toBeCloseTo(3);
    await journal.flush();

    const replay = await loadReplayCache(store, "run_stream");
    const replayMeter = createBudgetMeter(10);
    const fresh = new MockLanguageModelV3({
      provider: "mock-provider",
      modelId: "claude-sonnet-4-6",
    });
    const replayUsage = createRunUsage();
    const replayModel = engineModel(fresh as unknown as ResolvedModel, {
      role: "write",
      grant: replayMeter,
      pricing: PRICING,
      gate: createConcurrencyGate(2),
      usage: replayUsage,
      replay,
    });
    const replayed = streamText({
      model: replayModel as LanguageModelV3,
      prompt: "hi",
    });
    let replayedText = "";
    for await (const delta of replayed.textStream) replayedText += delta;
    expect(replayedText).toBe("hello world");
    expect(fresh.doStreamCalls).toHaveLength(0);
    expect(replayMeter.totalSpentUSD()).toBeCloseTo(3);
    expect(replayUsage.replayedUSD).toBeCloseTo(3);
  });

  it("charges the reserved estimate when a stream ends without a finish part", async () => {
    const meter = createBudgetMeter(10);
    const inner = new MockLanguageModelV3({
      provider: "mock-provider",
      modelId: "claude-sonnet-4-6",
      doStream: async () => ({
        stream: simulateReadableStream<LanguageModelV3StreamPart>({
          chunks: [
            { type: "stream-start", warnings: [] },
            { type: "text-start", id: "t1" },
            { type: "text-delta", id: "t1", delta: "partial" },
          ],
        }),
      }),
    });
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "write",
      grant: meter,
      pricing: PRICING,
      gate: createConcurrencyGate(2),
      usage: createRunUsage(),
    });
    const { stream } = await model.doStream({
      prompt: [{ role: "user", content: [{ type: "text", text: "hi" }] }],
    } as Parameters<LanguageModelV3["doStream"]>[0]);
    const reader = stream.getReader();
    while (!(await reader.read()).done) {}
    const spent = meter.totalSpentUSD();
    expect(spent).toBeGreaterThan(0);
    expect(meter.remainingUSD()).toBeCloseTo(10 - spent);
  });

  it("holds the concurrency slot for the whole stream, not just setup", async () => {
    const gate = createConcurrencyGate(1);
    const inner = streamingMock();
    const model = engineModel(inner as unknown as ResolvedModel, {
      role: "write",
      grant: createBudgetMeter(10),
      pricing: PRICING,
      gate,
      usage: createRunUsage(),
    });
    const { stream } = await model.doStream({
      prompt: [{ role: "user", content: [{ type: "text", text: "hi" }] }],
    } as Parameters<LanguageModelV3["doStream"]>[0]);

    let competitorRan = false;
    const competitor = gate.run(async () => {
      competitorRan = true;
    });
    await Promise.resolve();
    await Promise.resolve();
    expect(competitorRan).toBe(false);

    const reader = stream.getReader();
    while (!(await reader.read()).done) {}
    await competitor;
    expect(competitorRan).toBe(true);
  });
});

describe("totalFreshTokens", () => {
  it("sums input, output, and cache writes but ignores cache reads", () => {
    const usage = createRunUsage();
    usage.byRole.set("lead", {
      input: 1_000,
      output: 200,
      cacheRead: 50_000,
      cacheWrite: 300,
    });
    usage.byRole.set("verify", {
      input: 400,
      output: 100,
      cacheRead: 0,
      cacheWrite: 0,
    });
    expect(totalFreshTokens(usage)).toBe(1_000 + 200 + 300 + 400 + 100);
  });

  it("is zero for a fresh usage tally", () => {
    expect(totalFreshTokens(createRunUsage())).toBe(0);
  });
});

describe("normalizeForCacheKey", () => {
  it("collapses the volatile budget status line to a stable token", () => {
    expect(
      normalizeForCacheKey("plan\n[budget: ≈$9.80 of $10.00 remaining]"),
    ).toBe(normalizeForCacheKey("plan\n[budget: ≈$2.13 of $10.00 remaining]"));
  });

  it("collapses a negative overshoot readout to the same token as a positive one", () => {
    expect(normalizeForCacheKey("[budget: ≈$-1.23 of $10.00 remaining]")).toBe(
      normalizeForCacheKey("[budget: ≈$9.80 of $10.00 remaining]"),
    );
  });

  it("collapses thousands-separated amounts too", () => {
    expect(
      normalizeForCacheKey("[budget: ≈$1,234.56 of $5,000.00 remaining]"),
    ).toBe(normalizeForCacheKey("[budget: ≈$0.01 of $5,000.00 remaining]"));
  });

  it("collapses the remaining-budget continuation anchor", () => {
    expect(normalizeForCacheKey("Remaining research budget: ≈$2.50.")).toBe(
      normalizeForCacheKey("Remaining research budget: ≈$0.10."),
    );
  });

  it("redacts only the volatile figure and keeps the constant total", () => {
    expect(normalizeForCacheKey("budget: ≈$3.10 of $10.00 remaining")).toBe(
      "budget: ≈$ of $10.00 remaining",
    );
  });

  it("preserves exact $ figures so real content still distinguishes prompts", () => {
    expect(normalizeForCacheKey("price $5.00")).not.toBe(
      normalizeForCacheKey("price $7.00"),
    );
  });

  it("leaves a bare ≈$ figure in source content untouched", () => {
    expect(normalizeForCacheKey("street value ≈$50.00 today")).toBe(
      "street value ≈$50.00 today",
    );
    expect(normalizeForCacheKey("street value ≈$50.00 today")).not.toBe(
      normalizeForCacheKey("street value ≈$90.00 today"),
    );
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import { perplexityAgent } from "./perplexity-agent.js";

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("perplexityAgent cost", () => {
  it("computes cost from usage tokens at sonar-deep-research rates", async () => {
    vi.stubGlobal(
      "fetch",
      async () =>
        new Response(
          JSON.stringify({
            choices: [{ message: { content: "answer" } }],
