  prompt_tokens?: number;
  completion_tokens?: number;
  citation_tokens?: number;
  reasoning_tokens?: number;
  num_search_queries?: number;
}

interface PerplexityResponse {
  choices?: Array<{ message?: { content?: string } }>;
  citations?: string[];
  search_results?: Array<{ url?: string; title?: string }>;
  usage?: PerplexityUsage;
}

function perplexityCost(
  usage: PerplexityUsage | undefined,
  model: string,
  override: Partial<PerplexityPricing> | undefined,
): number | undefined {
  if (!usage) return undefined;
  const r = { ...(PERPLEXITY_RATES[model] ?? FALLBACK_RATES), ...override };
  return (
    ((usage.prompt_tokens ?? 0) * r.inputPerMTok +
      (usage.completion_tokens ?? 0) * r.outputPerMTok +
      (usage.citation_tokens ?? 0) * r.citationPerMTok +
      (usage.reasoning_tokens ?? 0) * r.reasoningPerMTok) /
      1_000_000 +
    ((usage.num_search_queries ?? 0) / 1000) * r.perThousandSearches
  );
}

export function perplexityAgent(opts: PerplexityAgentOptions = {}): Researcher {
  const apiKey =
    opts.apiKey ?? readEnv("ATLAS_PERPLEXITY_API_KEY", "PERPLEXITY_API_KEY");
  const endpoint = `${(opts.baseUrl ?? "https://api.perplexity.ai").replace(/\/+$/, "")}/chat/completions`;
  return {
    description: opts.description ?? DEFAULT_DESCRIPTION,
    async research(query, ctx) {
      if (!apiKey) {
        throw new Error(
          "perplexity.agent: no API key (set ATLAS_PERPLEXITY_API_KEY / PERPLEXITY_API_KEY or pass { apiKey })",
        );
      }
      const model = opts.model ?? "sonar-deep-research";
      const data = await withTimeout(
        opts.timeoutMs ?? DEFAULT_TIMEOUT_MS,
        ctx.signal,
        "perplexity.agent",
        async (signal) => {
          const resp = await fetch(endpoint, {
            method: "POST",
            signal,
            headers: {
              "content-type": "application/json",
              authorization: `Bearer ${apiKey}`,
            },
            body: JSON.stringify({
              model,
              messages: [{ role: "user", content: query }],
            }),
          });
          if (!resp.ok) {
            throw new Error(`perplexity.agent: HTTP ${resp.status}`);
          }
          return (await resp.json()) as PerplexityResponse;
        },
      );
      if (!data.choices || data.choices.length === 0) {
        throw new Error(
          "perplexity.agent: response had no choices (HTTP 200 with an error body?)",
        );
      }
      const report = (data.choices[0]?.message?.content ?? "").trim();
      const fromResults = (data.search_results ?? [])
        .filter((r): r is { url: string; title?: string } => Boolean(r.url))
        .map((r) => ({ url: r.url, ...(r.title ? { title: r.title } : {}) }));
      const sources =
        fromResults.length > 0
          ? fromResults
          : (data.citations ?? []).map((url) => ({ url }));
      const cost = perplexityCost(data.usage, model, opts.pricing);
      ctx.log(
        `perplexity.agent: ${sources.length} sources` +
          (cost != null
            ? `, $${cost.toFixed(4)}`
            : " (cost unknown — no usage in response)"),
      );
      return { report, sources, ...(cost != null ? { cost } : {}) };
    },
  };
}

import { sleep, withTimeout } from "../async.js";
import { readEnv } from "../env.js";
import type { Researcher } from "../researcher.js";

export interface ParallelAgentOptions {
  apiKey?: string;
  baseUrl?: string;
  processor?: string;
  description?: string;
  timeoutMs?: number;
  pollIntervalMs?: number;
  costPerRunUSD?: number;
}

const PARALLEL_PRICE_PER_RUN: Record<string, number> = {
  lite: 0.005,
  base: 0.01,
  core: 0.025,
  core2x: 0.05,
  pro: 0.1,
  ultra: 0.3,
  ultra2x: 0.6,
  ultra4x: 1.2,
  ultra8x: 2.4,
};

const DEFAULT_TIMEOUT_MS = 15 * 60_000;
const DEFAULT_POLL_INTERVAL_MS = 3_000;
const TERMINAL_STATUSES = new Set([
  "completed",
  "failed",
  "cancelled",
  "cancelling",
  "error",
]);

const DEFAULT_DESCRIPTION =
  "Parallel.ai task research: autonomous web research returning a citation-backed result. Strong on enrichment, structured/entity extraction, and broad gathering.";

interface ParallelResult {
  output?: {
    content?: unknown;
    basis?: Array<{ citations?: Array<{ url?: string; title?: string }> }>;
  };
}

export function parallelAgent(opts: ParallelAgentOptions = {}): Researcher {
  const apiKey =
    opts.apiKey ?? readEnv("ATLAS_PARALLEL_API_KEY", "PARALLEL_API_KEY");
  const base = (opts.baseUrl ?? "https://api.parallel.ai").replace(/\/+$/, "");
  return {
    description: opts.description ?? DEFAULT_DESCRIPTION,
    async research(query, ctx) {
      if (!apiKey) {
        throw new Error(
          "parallel.agent: no API key (set ATLAS_PARALLEL_API_KEY / PARALLEL_API_KEY or pass { apiKey })",
        );
      }
      const headers = {
        "content-type": "application/json",
        "x-api-key": apiKey,
      };
      const processor = opts.processor ?? "core";
      const data = await withTimeout(
        opts.timeoutMs ?? DEFAULT_TIMEOUT_MS,
        ctx.signal,
        "parallel.agent",
        async (signal): Promise<ParallelResult> => {
          const created = await fetch(`${base}/v1/tasks/runs`, {
            method: "POST",
            signal,
            headers,
            body: JSON.stringify({
              input: query,
              processor,
            }),
          });
          if (!created.ok) {
            throw new Error(`parallel.agent: create HTTP ${created.status}`);
          }
          const run = (await created.json()) as {
            run_id?: string;
            status?: string;
          };
          if (!run.run_id) {
            throw new Error("parallel.agent: no run_id in create response");
          }
          let status = run.status ?? "queued";
          while (!TERMINAL_STATUSES.has(status)) {
            await sleep(
              opts.pollIntervalMs ?? DEFAULT_POLL_INTERVAL_MS,
              signal,
            );
            const polled = await fetch(`${base}/v1/tasks/runs/${run.run_id}`, {
              signal,
              headers,
            });
            if (!polled.ok) {
              throw new Error(`parallel.agent: poll HTTP ${polled.status}`);
            }
            status =
              ((await polled.json()) as { status?: string }).status ?? status;
          }
          if (status !== "completed") {
            throw new Error(`parallel.agent: task run ${status}`);
          }
          const resultResp = await fetch(
            `${base}/v1/tasks/runs/${run.run_id}/result`,
            { signal, headers },
          );
          if (!resultResp.ok) {
            throw new Error(`parallel.agent: result HTTP ${resultResp.status}`);
          }
          return (await resultResp.json()) as ParallelResult;
        },
      );
      const content = data.output?.content;
      const report = (
        typeof content === "string" ? content : JSON.stringify(content ?? "")
      ).trim();
      const seen = new Set<string>();
      const sources: { url: string; title?: string }[] = [];
      for (const field of data.output?.basis ?? []) {
        for (const citation of field.citations ?? []) {
          if (citation.url && !seen.has(citation.url)) {
            seen.add(citation.url);
            sources.push({
              url: citation.url,
              ...(citation.title ? { title: citation.title } : {}),
            });
          }
        }
      }
      const cost = opts.costPerRunUSD ?? PARALLEL_PRICE_PER_RUN[processor];
      ctx.log(
        `parallel.agent: ${sources.length} sources` +
          (cost != null
            ? `, $${cost.toFixed(4)}`
            : " (cost unknown — set costPerRunUSD)"),
      );
      return { report, sources, ...(cost != null ? { cost } : {}) };
    },
  };
}

import { generateText, type LanguageModel, type ToolSet } from "ai";
import { sleep } from "../async.js";
import { isZaiModelId } from "../defaults.js";
import { readEnv } from "../env.js";
import { errorMessage } from "../errors.js";
import { normalizeUrlForSource } from "../url.js";

export interface SearchResult {
  position: number;
  title: string;
  url: string;
  snippet: string;
  domain: string;
  meta?: Record<string, unknown>;
}

export interface SearchQuery {
  query: string;
  maxResults?: number;
  signal?: AbortSignal;
}

export interface SearchProvider {
  readonly id: string;
  search(q: SearchQuery): Promise<SearchResult[]>;
}

export function safeDomain(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

function toResult(
  index: number,
  url: unknown,
  title: unknown,
  snippet: string,
): SearchResult | null {
  if (typeof url !== "string" || !/^https?:\/\//i.test(url)) return null;
  return {
    position: index + 1,
    title: typeof title === "string" && title.trim() ? title.trim() : url,
    url,
    snippet,
    domain: safeDomain(url),
  };
}

async function readErrorBody(resp: Response): Promise<string> {
  try {
    const text = (await resp.text()).trim();
    return text.length > 200 ? `${text.slice(0, 200)}…` : text;
  } catch {
    return "";
  }
}

class SearchProviderError extends Error {
  readonly statusCode: number;
  readonly retryAfterMs?: number;
  constructor(message: string, statusCode: number, retryAfterMs?: number) {
    super(message);
    this.name = "SearchProviderError";
    this.statusCode = statusCode;
    if (retryAfterMs !== undefined) this.retryAfterMs = retryAfterMs;
  }
}

function parseRetryAfterMs(headers: Headers): number | undefined {
  const raw = headers.get("retry-after");
  if (!raw) return undefined;
  const seconds = Number(raw);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1_000);
  const at = Date.parse(raw);
  if (Number.isFinite(at)) return Math.max(0, at - Date.now());
  return undefined;
}

async function searchHttpError(
  label: string,
  resp: Response,
): Promise<SearchProviderError> {
  const body = await readErrorBody(resp);
  return new SearchProviderError(
    `${label}: HTTP ${resp.status}: ${body}`,
    resp.status,
    parseRetryAfterMs(resp.headers),
  );
}

const SEARCH_RETRY_MAX_ATTEMPTS = 5;
const SEARCH_RETRY_BASE_DELAY_MS = 500;
const SEARCH_RETRY_MAX_DELAY_MS = 15_000;

function classifySearchRetry(err: unknown): {
  retryable: boolean;
  retryAfterMs?: number;
} {
  if (
    err instanceof Error &&
    (err.name === "AbortError" || err.name === "TimeoutError")
  ) {
    return { retryable: false };
  }
  if (err instanceof SearchProviderError) {
    const status = err.statusCode;
    const retryable =
      status === 408 || status === 409 || status === 429 || status >= 500;
    if (!retryable) return { retryable: false };
    return {
      retryable: true,
      ...(err.retryAfterMs !== undefined
        ? { retryAfterMs: err.retryAfterMs }
        : {}),
    };
  }
  const message = (
    err instanceof Error ? err.message : String(err)
  ).toLowerCase();
  return /rate limit|too many requests|overloaded|concurrent connections|timeout|timed out|econnreset|etimedout|eai_again|socket hang up|fetch failed|network error/.test(
    message,
  )
    ? { retryable: true }
    : { retryable: false };
}

function searchBackoffDelayMs(
  attempt: number,
  retryAfterMs: number | undefined,
): number {
  const exponential = Math.min(
    SEARCH_RETRY_MAX_DELAY_MS,
    SEARCH_RETRY_BASE_DELAY_MS * 2 ** (attempt - 1),
  );
  const jittered = exponential / 2 + Math.random() * (exponential / 2);
  return Math.min(
    SEARCH_RETRY_MAX_DELAY_MS,
    Math.max(retryAfterMs ?? 0, jittered),
  );
}

async function searchWithRetry(
  provider: SearchProvider,
  q: SearchQuery,
): Promise<SearchResult[]> {
  let tries = 0;
  for (;;) {
    tries++;
    try {
      return await provider.search(q);
    } catch (err) {
      const { retryable, retryAfterMs } = classifySearchRetry(err);
      if (
        !retryable ||
        tries >= SEARCH_RETRY_MAX_ATTEMPTS ||
        q.signal?.aborted
      ) {
        throw err;
      }
      await sleep(searchBackoffDelayMs(tries, retryAfterMs), q.signal);
    }
  }
}

function clampLimit(limit: number | undefined, max: number): number {
  return Math.min(Math.max(1, Math.floor(limit ?? 8)), max);
}

export interface TavilyOptions {
  apiKey?: string;
  baseUrl?: string;
}

export function tavily(opts: TavilyOptions = {}): SearchProvider {
  const apiKey =
    opts.apiKey ?? readEnv("ATLAS_TAVILY_API_KEY", "TAVILY_API_KEY");
  if (!apiKey) {
    throw new Error(
      "tavily() requires an apiKey (or set ATLAS_TAVILY_API_KEY / TAVILY_API_KEY)",
    );
  }
  const endpoint = `${(opts.baseUrl ?? "https://api.tavily.com").replace(/\/+$/, "")}/search`;
  return {
    id: "tavily",
    async search({ query, maxResults, signal }) {
      const resp = await fetch(endpoint, {
        method: "POST",
        signal: signal ?? null,
        headers: {
          "content-type": "application/json",
          authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify({
          query,
          max_results: clampLimit(maxResults, 20),
        }),
      });
      if (!resp.ok) {
        throw await searchHttpError("tavily", resp);
      }
      const data = (await resp.json()) as { results?: unknown[] };
      const rows = Array.isArray(data.results) ? data.results : [];
      const results: SearchResult[] = [];
      for (const row of rows) {
        if (!row || typeof row !== "object") continue;
        const record = row as Record<string, unknown>;
        const snippet =
          typeof record.content === "string"
            ? record.content.slice(0, 500).trim()
            : "";
        const result = toResult(
          results.length,
          record.url,
          record.title,
          snippet,
        );
        if (result) results.push(result);
      }
      return results;
    },
  };
}

export interface ExaOptions {
  apiKey?: string;
  baseUrl?: string;
  type?: string;
}

export function exa(opts: ExaOptions = {}): SearchProvider {
  const apiKey = opts.apiKey ?? readEnv("ATLAS_EXA_API_KEY", "EXA_API_KEY");
  if (!apiKey) {
    throw new Error(
      "exa() requires an apiKey (or set ATLAS_EXA_API_KEY / EXA_API_KEY)",
    );
  }
  const endpoint = `${(opts.baseUrl ?? "https://api.exa.ai").replace(/\/+$/, "")}/search`;
  return {
    id: "exa",
    async search({ query, maxResults, signal }) {
      const resp = await fetch(endpoint, {
        method: "POST",
        signal: signal ?? null,
        headers: {
          "content-type": "application/json",
          "x-api-key": apiKey,
        },
        body: JSON.stringify({
          query,
          numResults: clampLimit(maxResults, 100),
          ...(opts.type ? { type: opts.type } : {}),
          contents: { highlights: { numSentences: 3, highlightsPerUrl: 2 } },
        }),
      });
      if (!resp.ok) {
        throw await searchHttpError("exa", resp);
      }
      const data = (await resp.json()) as { results?: unknown[] };
      const rows = Array.isArray(data.results) ? data.results : [];
      const results: SearchResult[] = [];
      for (const row of rows) {
        if (!row || typeof row !== "object") continue;
        const record = row as Record<string, unknown>;
        const highlights = Array.isArray(record.highlights)
          ? record.highlights.filter((h): h is string => typeof h === "string")
          : [];
        const snippet =
          highlights.join(" … ").trim() ||
          (typeof record.text === "string"
            ? record.text.slice(0, 500).trim()
            : "");
        const result = toResult(
          results.length,
          record.url,
          record.title,
          snippet,
        );
        if (result) results.push(result);
      }
      return results;
    },
  };
}

export interface BraveOptions {
  apiKey?: string;
  baseUrl?: string;
  country?: string;
  searchLang?: string;
}

export function brave(opts: BraveOptions = {}): SearchProvider {
  const apiKey = opts.apiKey ?? readEnv("ATLAS_BRAVE_API_KEY", "BRAVE_API_KEY");
  if (!apiKey) {
    throw new Error(
      "brave() requires an apiKey (or set ATLAS_BRAVE_API_KEY / BRAVE_API_KEY)",
    );
  }
  const base = `${(opts.baseUrl ?? "https://api.search.brave.com").replace(/\/+$/, "")}/res/v1/web/search`;
  return {
    id: "brave",
    async search({ query, maxResults, signal }) {
      const params = new URLSearchParams({
        q: query,
        count: String(clampLimit(maxResults, 20)),
        extra_snippets: "true",
      });
      if (opts.country) params.set("country", opts.country);
      if (opts.searchLang) params.set("search_lang", opts.searchLang);
      const resp = await fetch(`${base}?${params.toString()}`, {
        signal: signal ?? null,
        headers: {
          accept: "application/json",
          "x-subscription-token": apiKey,
        },
      });
      if (!resp.ok) {
        throw await searchHttpError("brave", resp);
      }
      const data = (await resp.json()) as { web?: { results?: unknown[] } };
      const rows = Array.isArray(data.web?.results) ? data.web.results : [];
      const results: SearchResult[] = [];
      for (const row of rows) {
        if (!row || typeof row !== "object") continue;
        const record = row as Record<string, unknown>;
        const extra = Array.isArray(record.extra_snippets)
          ? record.extra_snippets.filter(
              (s): s is string => typeof s === "string",
            )
          : [];
        const snippet =
          (typeof record.description === "string" ? record.description : "") ||
          extra.join(" … ");
        const result = toResult(
          results.length,
          record.url,
          record.title,
          snippet.trim(),
        );
        if (result) results.push(result);
      }
      return results;
    },
  };
}

export interface NativeModelSearchOptions {
  model: Exclude<LanguageModel, string>;
}

export function nativeModelSearch(
  opts: NativeModelSearchOptions,
): SearchProvider {
  return {
    id: "model-native",
    async search({ query, maxResults, signal }) {
      const tools = await nativeSearchTools(opts.model);
      const limit = clampLimit(maxResults, 10);
      const result = await generateText({
        model: opts.model,
        prompt:
          `Search the web for: ${query}\n\n` +
          `Run one web search and list the ${limit} most relevant distinct result pages. ` +
          "Do not answer the question; just surface the sources. " +
          "Write one line per result in the form `<plain url> :: <one-sentence summary of what the page contains>`, with no markdown links.",
        tools,
        maxOutputTokens: 1_500,
        abortSignal: signal,
      });
      const lines = parseResultLines(result.text);
      const summaryByKey = new Map<string, string>();
      for (const line of lines) {
        summaryByKey.set(normalizeUrlForSource(line.url), line.summary);
      }
      const seen = new Set<string>();
      const results: SearchResult[] = [];
      const add = (url: unknown, title: unknown, snippet: string) => {
        if (results.length >= limit || typeof url !== "string") return;
        const key = normalizeUrlForSource(url);
        if (seen.has(key)) return;
        const parsed = toResult(results.length, url, title, snippet);
        if (!parsed) return;
        seen.add(key);
        results.push(parsed);
      };
      for (const source of result.sources) {
        if (source.sourceType !== "url") continue;
        const key = normalizeUrlForSource(source.url);
        add(source.url, source.title, summaryByKey.get(key) ?? "");
      }
      for (const line of lines) add(line.url, undefined, line.summary);
      return results;
    },
  };
}

function parseResultLines(text: string): { url: string; summary: string }[] {
  const out: { url: string; summary: string }[] = [];
  const seen = new Set<string>();
  for (const line of text.split("\n")) {
    const match = /(https?:\/\/\S+?)[)\]>.,]*\s*::\s*(\S.*)/.exec(line);
    if (!match) continue;
    const key = normalizeUrlForSource(match[1]);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ url: match[1], summary: match[2].trim().slice(0, 500) });
  }
  return out;
}

async function importProvider<T>(
  pkg: string,
  load: () => Promise<T>,
): Promise<T> {
  try {
    return await load();
  } catch (err) {
    throw new Error(
      `nativeModelSearch needs "${pkg}" installed for this provider's server-side search; ` +
        `install it (npm install ${pkg}) or configure a search adapter (tavily(), exa(), brave()). ` +
        `Original error: ${errorMessage(err)}`,
    );
  }
}

async function nativeSearchTools(
  model: Exclude<LanguageModel, string>,
): Promise<ToolSet> {
  const provider = model.provider.toLowerCase();
  if (isZaiModelId(model.modelId)) {
    throw new Error(
      `nativeModelSearch: provider "${model.provider}" has no known server-side search tool; configure a search adapter (tavily(), exa(), brave())`,
    );
  }
  if (provider.includes("anthropic")) {
    const { anthropic } = await importProvider(
      "@ai-sdk/anthropic",
      () => import("@ai-sdk/anthropic"),
    );
    return {
      web_search: anthropic.tools.webSearch_20250305({ maxUses: 1 }),
    };
  }
  if (provider.includes("openai")) {
    const { openai } = await importProvider(
      "@ai-sdk/openai",
      () => import("@ai-sdk/openai"),
    );
    return { web_search: openai.tools.webSearch({}) };
  }
  if (provider.includes("google")) {
    const { google } = await importProvider(
      "@ai-sdk/google",
      () => import("@ai-sdk/google"),
    );
    return { google_search: google.tools.googleSearch({}) };
  }
  throw new Error(
    `nativeModelSearch: provider "${model.provider}" has no known server-side search tool; configure a search adapter (tavily(), exa(), brave())`,
  );
}

export interface MergedSearchResult {
  title: string;
  url: string;
  snippet: string;
  provider: string;
  providerRank: number;
  providers: string[];
  score: number;
  meta?: Record<string, unknown>;
}

const RRF_K = 60;

export function openUrlsOf(
  meta: Record<string, unknown> | undefined,
): string[] {
  const raw = meta?.openUrls;
  if (!Array.isArray(raw)) return [];
  const out: string[] = [];
  for (const url of raw) {
    if (typeof url === "string" && /^https?:\/\//i.test(url)) out.push(url);
  }
  return out;
}

function mergeMeta(
  existing: Record<string, unknown> | undefined,
  incoming: Record<string, unknown> | undefined,
  preferIncoming: boolean,
): Record<string, unknown> | undefined {
  const openUrls = [
    ...new Set([...openUrlsOf(existing), ...openUrlsOf(incoming)]),
  ];
  const base = preferIncoming
    ? { ...existing, ...incoming }
    : { ...incoming, ...existing };
  if (openUrls.length === 0) {
    return Object.keys(base).length > 0 ? base : undefined;
  }
  return { ...base, openUrls };
}

export function mergeSearchResults(
  lists: Array<{ provider: string; results: SearchResult[] }>,
  limit: number,
): MergedSearchResult[] {
  const byUrl = new Map<string, MergedSearchResult>();
  for (const list of lists) {
    for (const result of list.results) {
      const key = normalizeUrlForSource(result.url);
      const score = 1 / (RRF_K + result.position);
      const existing = byUrl.get(key);
      if (!existing) {
        byUrl.set(key, {
          title: result.title,
          url: result.url,
          snippet: result.snippet,
          provider: list.provider,
          providerRank: result.position,
          providers: [list.provider],
          score,
          ...(result.meta ? { meta: result.meta } : {}),
        });
        continue;
      }
      existing.score += score;
      if (!existing.providers.includes(list.provider)) {
        existing.providers.push(list.provider);
      }
      const betterRank = result.position < existing.providerRank;
      if (betterRank) {
        existing.title = result.title;
        existing.url = result.url;
        existing.snippet = result.snippet || existing.snippet;
        existing.provider = list.provider;
        existing.providerRank = result.position;
      }
      const meta = mergeMeta(existing.meta, result.meta, betterRank);
      if (meta) existing.meta = meta;
    }
  }
  return [...byUrl.values()]
    .sort((a, b) => b.score - a.score || a.providerRank - b.providerRank)
    .slice(0, limit);
}

export interface ResolvedSearch {
  providers: SearchProvider[];
  run(q: SearchQuery): Promise<{
    merged: MergedSearchResult[];
    warnings: string[];
  }>;
}

export function combineSearchProviders(
  providers: SearchProvider[],
): ResolvedSearch {
  return {
    providers,
    async run(q) {
      const warnings: string[] = [];
      const lists = await Promise.all(
        providers.map(async (provider) => {
          try {
            return {
              provider: provider.id,
              results: await searchWithRetry(provider, q),
            };
          } catch (err) {
            warnings.push(`${provider.id}: ${errorMessage(err)}`);
            return { provider: provider.id, results: [] };
          }
        }),
      );
      return {
        merged: mergeSearchResults(lists, clampLimit(q.maxResults, 20)),
        warnings,
      };
    },
  };
}

export function defaultSearchProviders(
  model: Exclude<LanguageModel, string>,
): SearchProvider[] {
  const providers: SearchProvider[] = [];
  if (readEnv("ATLAS_TAVILY_API_KEY", "TAVILY_API_KEY")) {
    providers.push(tavily());
  }
  if (readEnv("ATLAS_EXA_API_KEY", "EXA_API_KEY")) {
    providers.push(exa());
  }
  if (readEnv("ATLAS_BRAVE_API_KEY", "BRAVE_API_KEY")) {
    providers.push(brave());
  }
  if (providers.length > 0) return providers;
  return [nativeModelSearch({ model })];
}

export interface ModelPrice {
  input: number;
  output: number;
}

const PRICES: Record<string, ModelPrice> = {
  "claude-opus-4-8": { input: 5, output: 25 },
  "claude-opus-4-7": { input: 5, output: 25 },
  "claude-opus-4-6": { input: 5, output: 25 },
  "claude-opus-4-5": { input: 5, output: 25 },
  "claude-sonnet-4-6": { input: 3, output: 15 },
  "claude-sonnet-4-5": { input: 3, output: 15 },
  "claude-haiku-4-5": { input: 1, output: 5 },
};

const CACHE_READ_MULTIPLIER = 0.1;
const CACHE_WRITE_MULTIPLIER = 1.25;

export interface TokenUsage {
  input?: number;
  output?: number;
  cacheRead?: number;
  cacheWrite?: number;
  model?: string | null;
}

export interface CostBreakdown {
  model: string | null;
  priced: boolean;
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
  totalTokens: number;
  usd: number | null;
}

function priceFor(model: string | null | undefined): ModelPrice | undefined {
  if (!model) return undefined;
  const bare = model.includes(".")
    ? model.split(".").slice(1).join(".")
    : model;
  return PRICES[model] ?? PRICES[bare];
}

export function costOf(usage: TokenUsage): CostBreakdown {
  const input = usage.input ?? 0;
  const output = usage.output ?? 0;
  const cacheRead = usage.cacheRead ?? 0;
  const cacheWrite = usage.cacheWrite ?? 0;
  const price = priceFor(usage.model);
  const usd = price
    ? (input * price.input +
        cacheWrite * price.input * CACHE_WRITE_MULTIPLIER +
        cacheRead * price.input * CACHE_READ_MULTIPLIER +
        output * price.output) /
      1_000_000
    : null;
  return {
    model: usage.model ?? null,
    priced: price !== undefined,
    inputTokens: input,
    outputTokens: output,
    cacheReadTokens: cacheRead,
    cacheWriteTokens: cacheWrite,
    totalTokens: input + output + cacheRead + cacheWrite,
    usd: usd === null ? null : Number(usd.toFixed(4)),
  };
}

export interface RunUsage {
  research?: TokenUsage | null;
  leaf?: TokenUsage | null;
  judge?: (TokenUsage & { calls?: number; gradeRuns?: number }) | null;
}

export interface RunCost {
  research: CostBreakdown | null;
  leaf: CostBreakdown | null;
  judge: CostBreakdown | null;
  totalUsd: number | null;
}

export function runCost(usage: RunUsage | null | undefined): RunCost {
  const research = usage?.research ? costOf(usage.research) : null;
  const leaf = usage?.leaf ? costOf(usage.leaf) : null;
  const judge = usage?.judge ? costOf(usage.judge) : null;
  const parts = [research?.usd, leaf?.usd, judge?.usd].filter(
    (v): v is number => typeof v === "number",
  );
  const totalUsd =
    parts.length > 0
      ? Number(parts.reduce((s, v) => s + v, 0).toFixed(4))
      : null;
  return { research, leaf, judge, totalUsd };
}

